    DefaultTableModel m=model("ID","Línea","Origen","Destino","Peso","Contenido","Estado");JTable t=table(m);JLabel msg=new JLabel(" ");final List<Map<String,Object>> rows=new ArrayList<>();
    JPanel tableBox=new JPanel(new BorderLayout(4,4));tableBox.setOpaque(false);tableBox.setBorder(BorderFactory.createEmptyBorder(8,0,0,0));tableBox.add(new JLabel("Envíos registrados"),BorderLayout.NORTH);tableBox.add(new JScrollPane(t),BorderLayout.CENTER);content.add(tableBox);
