  private static void initializeGuide(Map<String,Object> shipment){String id=idOf(shipment);if(GUIDE_HISTORY.containsKey(id))return;GUIDE_STATES.put(id,"COTIZADO");GUIDE_HISTORY.put(id,new ArrayList<>(List.of(guideTimestamp()+"  COTIZADO — "+val(shipment,"origen")+": Tarifa confirmada y guía simulada a partir de la boleta.")));}
