  private JPanel ruleSimulationPanel(){
    JPanel p=new JPanel(new BorderLayout(8,8));p.setOpaque(false);JPanel form=formGrid();JTextField kg=field(form,"Peso envío (kg)","2.5"),max=field(form,"Límite máx. (kg)","10");JComboBox<String> line=combo(form,"Línea de negocio","Personal (x1.00)","Empresarial (x1.10)","Encomienda (x1.20)","Filatelia (x0.90)");JTextField base=field(form,"Tarifa base (S/)","10"),perKg=field(form,"Costo por kg (S/)","3.5"),tax=field(form,"IGV (%)","18"),blocked=field(form,"Palabras prohibidas (separadas por coma)","explosivo, inflamable, arma, narcótico"),sample=field(form,"Contenido de prueba","Documentos y libros");
    JPanel box=new JPanel(new BorderLayout(6,8));box.setBackground(Color.WHITE);box.setBorder(BorderFactory.createTitledBorder("Parámetros de reglas postales y simulación en vivo"));box.add(form,BorderLayout.CENTER);JPanel results=new JPanel(new FlowLayout(FlowLayout.LEFT,16,5));results.setOpaque(false);JLabel weightState=new JLabel("Peso pendiente"),contentState=new JLabel("Contenido pendiente"),dispatch=new JLabel("—"),subtotal=new JLabel("Subtotal: —"),total=new JLabel("Total c/IGV: —");for(JLabel label:List.of(weightState,contentState,dispatch,subtotal,total))results.add(label);box.add(results,BorderLayout.SOUTH);JButton evaluate=new JButton("Evaluar reglas");p.add(box,BorderLayout.CENTER);p.add(evaluate,BorderLayout.SOUTH);
    Runnable calc=()->{try{double w=Double.parseDouble(kg.getText().replace(',','.')),limit=Double.parseDouble(max.getText().replace(',','.')),b=Double.parseDouble(base.getText().replace(',','.')),rate=Double.parseDouble(perKg.getText().replace(',','.')),percent=Double.parseDouble(tax.getText().replace(',','.'));if(w<=0||limit<=0||b<0||rate<0||percent<0)throw new IllegalArgumentException("Revisa los valores: peso y límite deben ser positivos.");boolean validWeight=w<=limit;weightState.setText(validWeight?"Dentro del límite":"Supera el límite");weightState.setForeground(validWeight?new Color(30,110,80):Color.RED);String text=sample.getText().toLowerCase(Locale.ROOT);boolean validContent=true;for(String term:blocked.getText().split(",")){String word=term.trim().toLowerCase(Locale.ROOT);if(!word.isEmpty()&&text.contains(word)){validContent=false;break;}}contentState.setText(validContent?"Contenido permitido":"Contenido restringido");contentState.setForeground(validContent?new Color(30,110,80):Color.RED);String chosen=String.valueOf(line.getSelectedItem());double multiplier=chosen.startsWith("Empresarial")?1.10:chosen.startsWith("Encomienda")?1.20:chosen.startsWith("Filatelia")?.90:1.0;double sub=Math.round((b+w*rate)*multiplier*100)/100.0,all=Math.round(sub*(1+percent/100)*100)/100.0;subtotal.setText("Subtotal ("+chosen.split(" ")[0]+"): S/ "+String.format(Locale.US,"%.2f",sub));total.setText("Total c/IGV: S/ "+String.format(Locale.US,"%.2f",all));dispatch.setText(validWeight&&validContent?"APTO PARA DESPACHO":"NO APTO");dispatch.setForeground(validWeight&&validContent?new Color(30,110,80):Color.RED);}catch(Exception ex){message("No se pudo evaluar: "+ex.getMessage());}};
    evaluate.addActionListener(e->calc.run());calc.run();return p;
  }

